    void parsesQuotedAndUnquotedValuesAndDelegatesEachAttribute() throws TextParseException {
        final char[] buffer = "alpha='one two' beta=two".toCharArray();
        final RecordingHandler handler = new RecordingHandler();

        TextParsingAttributeSequenceUtil.parseAttributeSequence(
                buffer, 0, buffer.length, 1, 1, handler);

        assertEquals(2, handler.attributes.size());

        final Attribute first = handler.attributes.get(0);
        assertEquals("alpha", first.name);
        assertEquals("=", first.operator);
        assertEquals("one two", first.value);
        assertEquals("'one two'", first.outerValue);

        final Attribute second = handler.attributes.get(1);
        assertEquals("beta", second.name);
        assertEquals("=", second.operator);
        assertEquals("two", second.value);
        assertEquals("two", second.outerValue);
    }

